CREATE OR REPLACE PROCEDURE get_customer_count
AS
    l_count NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO   l_count
    FROM   customer_secure;

    DBMS_OUTPUT.PUT_LINE(
        'Customer count = ' || l_count
    );
END;
/

SET SERVEROUTPUT ON

BEGIN
    get_customer_count;
END;
/

CREATE OR REPLACE PROCEDURE get_customer_count
AS
    l_count NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO   l_count
    FROM   customer_secure
    WHERE  account_status='ACTIVE';

    DBMS_OUTPUT.PUT_LINE(
        'Active customer count = ' || l_count
    );
END;
/

SET SERVEROUTPUT ON

BEGIN
    get_customer_count;
END;
